"""Generate human-readable credits from the acquired/processed asset manifest."""
import csv, html, json
from pathlib import Path
root=Path(__file__).resolve().parent.parent
public=root/'apps/client/public/audio'
manifest_path=public/'asset-manifest.json'
manifest=json.loads(manifest_path.read_text(encoding='utf-8'))
triggers={
 'card-slide-1':'Selection/draw; Whisper activation; Scapegoat transfer; Doubt clearing',
 'card-slide-2':'Selection/draw; Whisper activation; Dawn; event dissolve; Doubt clearing',
 'card-place-1':'Card/event entrance; protection or Curse activation',
 'card-place-2':'Card/event entrance; Vow or protection activation; transfer arrival',
 'card-cut':'Selection/draw/flip; Eavesdrop, Dispel or failed-action activation',
 'card-contact':'Card place/flip; Eavesdrop activation',
 'card-shuffle':'Cinder Shift or Conspiracy activation',
 'wood-tap':'UI click; failed action; Resume the Hunt accent',
 'wood-impact':'Each visible Doubt stamp (once), seventh-mark impact, public Life portrait impact, elimination or verdict',
 'church-bell':'Council Bell wave activation at 10% of existing event duration',
 'page-flip':'Physical flip variation; public Life portrait entrance',
 'wood-creak':'Curse, transfer, Stocks, Night or elimination activation',
 'paper-swell':'Retained earlier physical-paper recording; not mapped by the current tonal glow cue catalogue',
 'metal-lock':'Stocks activation; public protection block; Bound release',
 'metal-resonance':'Successful public protection block resonance',
 'glow-rise':'Dark/mysterious finite event atmosphere; neutral reveal announcement; Whisper, Night, verdict and Resume the Hunt accents',
 'glow-reveal':'Warm helpful-event atmosphere; public Life portrait impact (warm/dark variants), magical activation, position and personal result accents',
}
for asset in manifest['assets']:
    if asset['filename'].startswith('metal-resonance.'):asset['purpose']='Successful public protection block resonance'
    if asset['filename'].startswith('paper-swell.'):asset['purpose']='Retained earlier paper-swell recording; current magical glow cues use JaggedStone tonal samples'
    asset['playbackTrigger']=triggers.get(asset['filename'].rsplit('.',1)[0],'Existing scene Music/Ambience playback; stable voice and playhead across ordinary updates')
    asset['licenceUrl']='https://creativecommons.org/licenses/by/4.0/' if asset['licence']=='CC-BY-4.0' else 'https://creativecommons.org/publicdomain/zero/1.0/'
    asset['attribution']='Phoenix (2026) by Scott Buckley - released under CC-BY 4.0. www.scottbuckley.com.au' if asset['licence']=='CC-BY-4.0' else f"{asset['creator']} (CC0; attribution optional)"
    asset['creationMethod']='Externally sourced recording; FFmpeg editing/transcoding'
manifest_path.write_text(json.dumps(manifest,indent=2),encoding='utf-8')
fields=['filename','kind','purpose','playbackTrigger','creator','sourceFile','sourceUrl','downloadUrl','licence','licenceUrl','attribution','processing','clip','creationMethod','bytes','durationSeconds','sha256']
with (root/'AUDIO_ASSET_CREDITS.csv').open('w',encoding='utf-8',newline='') as file:
    writer=csv.DictWriter(file,fields,extrasaction='ignore');writer.writeheader();writer.writerows(manifest['assets'])
seen=set();rows=[]
groups=[];seen_sources=set()
for source in manifest['sources']:
    if source['sourceUrl'] in seen_sources:continue
    seen_sources.add(source['sourceUrl'])
    assets=[a for a in manifest['assets'] if a['sourceUrl']==source['sourceUrl']]
    if not assets:continue
    first=assets[0]
    modifications='Loudness adjustment, resampling and Ogg/MP3 encoding.'
    if first['kind']=='music':modifications+=' Two-second circular loop crossfade.' if source['id'] not in ['victory','defeat'] else ' Trimmed into a short conclusion with fades.'
    elif first['kind']=='ambience':modifications+=' Excerpt, frequency filtering and a two-second circular loop crossfade.'
    else:
        modifications+=' Mono, with a short attack fade.'
        if source['id']=='church-bell':modifications+=' First 2.6 seconds selected.'
        if source['id']=='casino':modifications+=' A card shuffle is also reversed for the paper-swell effect.'
        if source['creator']=='JaggedStone':modifications+=' Trimmed to at most 2.4 seconds, with 15 ms entrance and 300 ms tail fades; these are prerecorded tonal spell effects.'
    groups.append({'title':source['title'],'creator':source['creator'],'sourceUrl':source['sourceUrl'],'licence':source['licence'],'licenceUrl':first['licenceUrl'],'required':source['licence']=='CC-BY-4.0','attribution':first['attribution'],'files':[a['filename'] for a in assets],'uses':list(dict.fromkeys(a['purpose'] for a in assets)),'modifications':modifications})
(root/'apps/client/src/credits-data.ts').write_text('// Generated by scripts/write-audio-credits.py from verified, shipped recordings.\nexport const AUDIO_CREDITS = '+json.dumps(groups,indent=2)+' as const;\n',encoding='utf-8')
for asset in manifest['assets']:
    name=asset['filename'].rsplit('.',1)[0]
    if name in seen:continue
    seen.add(name)
    rows.append(f"<tr><td>{html.escape(name)}.ogg / .mp3</td><td>{html.escape(asset['creator'])}</td><td><a href='{html.escape(asset['sourceUrl'])}'>Source</a> · <a href='{asset['licenceUrl']}'>{asset['licence']}</a></td><td>{html.escape(asset['purpose'])}<audio controls preload='none' aria-label='Preview {name}'><source src='{name}.ogg' type='audio/ogg'><source src='{name}.mp3' type='audio/mpeg'></audio></td></tr>")
document='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ashfall Council — Music &amp; sound credits</title>
<style>body{max-width:1000px;margin:auto;padding:28px 18px;color:#eee7d6;background:#0c0d11;font:15px/1.6 Georgia,serif}a{color:#e5c58b}table{border-collapse:collapse;width:100%;font:12px/1.6 Arial,sans-serif}td,th{border-bottom:1px solid #786b54;padding:12px 8px;text-align:left;overflow-wrap:anywhere}.scroll{overflow:auto}audio{display:block;width:220px;max-width:100%;height:36px;margin-top:8px}</style>
<h1>Music &amp; sound credits</h1><p>External music and recordings used in Ashfall Council. These are not original compositions by our team. Verified 31 October 2026.</p>
<h2>Music attribution</h2><p>“Phoenix (2026)” by Scott Buckley — released under <a href="https://creativecommons.org/licenses/by/4.0/">CC-BY 4.0</a>. <a href="https://www.scottbuckley.com.au/library/phoenix-2026/">www.scottbuckley.com.au</a>. Modifications: loudness adjustment, resampling, Ogg/MP3 encoding and a circular two-second loop crossfade.</p>
<p>Day: “Town in ruins loop” by Brandon Morris. Lobby: “Medieval: The Old Tower Inn”; Night: “Fantasy: Rising Moon”; results: “Medieval: Victory Theme” and “Medieval: Defeat Theme” by RandomMind. Card/table foley: Kenney and Brian MacIntosh (BMacZero). Page flip: yd. Wood creak: laleksic. Environments and church bell: Joseph SARDIN / BigSoundBank.com. These are CC0; source links are below. Backgrounds are normalized with loop seams edited; conclusions are eight and nine seconds. Supernatural paper swells reverse recorded shuffles.</p>
<h2>Included files</h2><p>Optional previews load only when played. They preview the edited file itself, without the game's volume settings or scene mixing.</p><div class="scroll"><table><thead><tr><th>Local filenames</th><th>Creator</th><th>Source / licence</th><th>In-game use / preview</th></tr></thead><tbody>'''+''.join(rows)+'''</tbody></table></div>
<p>All audio files are included with the game; no external streaming service or microphone is used. No AI audio-generation tool was used by this project. Codex assisted with processing/playback code. Programmatic filters, envelopes and ducking remain; oscillator/noise beds are retired.</p>
<p><a href="asset-manifest.json">Complete hashes and processing record</a> · <a href="licenses/kenney-casino.txt">Kenney Casino licence</a> · <a href="licenses/kenney-impacts.txt">Kenney Impact licence</a></p></html>'''
(public/'credits.html').write_text(document,encoding='utf-8')
(root/'docs/audio-source-records.json').write_text(json.dumps(manifest['sources'],indent=2),encoding='utf-8')
credit_public=root/'apps/client/public/credits'
credit_public.mkdir(exist_ok=True)
(credit_public/'software-notices.txt').write_text((root/'docs/audit/THIRD_PARTY_NOTICES.md').read_text(encoding='utf-8'),encoding='utf-8')
(credit_public/'project-notes.txt').write_text((root/'docs/ARTWORK.md').read_text(encoding='utf-8')+'\n\n'+(root/'docs/AI_USE_DECLARATION_DRAFT.md').read_text(encoding='utf-8'),encoding='utf-8')
